create or replace function private.vmc_create_profile_for_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.vmc_profiles(id,full_name,email,phone,must_change_password) values(new.id,coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),coalesce(new.email,'VMC Member')),new.email,nullif(trim(new.raw_user_meta_data->>'phone'),''),coalesce((new.raw_user_meta_data->>'must_change_password')::boolean,true)) on conflict(id) do nothing; insert into public.vmc_user_roles(user_id,role_id) select new.id,r.id from public.vmc_roles r where r.name='member' on conflict(user_id) do nothing; return new; end;$$;
revoke all on function private.vmc_create_profile_for_new_user() from public; grant execute on function private.vmc_create_profile_for_new_user() to postgres;
drop trigger if exists vmc_on_auth_user_created on auth.users; create trigger vmc_on_auth_user_created after insert on auth.users for each row execute function private.vmc_create_profile_for_new_user(); drop function if exists public.vmc_create_profile_for_new_user();